const items = $input.all();
const triggerItems = $('Google Sheets Trigger').all();

return items.map((item, index) => {

  const trigger = triggerItems[index]?.json || {};

  function getValue(name) {
    const key = Object.keys(trigger).find(k => k.trim() === name);
    return key ? trigger[key] : "";
  }

  return {
    json: {
      candidate: {
        name: getValue("Full Name"),
        email: getValue("Email Address"),
        phone: getValue("Phone Number"),
        position: getValue("Position Applying For"),
        experience: getValue("Years of Professional Experience"),
        linkedin: getValue("LinkedIn Profile"),
        github: getValue("GitHub Portfolio"),
        location: getValue("Current Location")
      },
      resume: item.json.text || ""
    }
  };
});

const items = $input.all();

/**
 * Better fuzzy matching
 */
function fuzzyMatch(requiredSkill, candidateSkills) {
  const req = requiredSkill.toLowerCase().trim();

  return candidateSkills.some(skill => {
    return (
      skill === req ||
      skill.includes(req) ||
      req.includes(skill)
    );
  });
}

/**
 * Extract years from strings like:
 * "2 years"
 * "1-2 years"
 * "3+ years"
 */
function extractYears(value) {
  if (!value) return 0;

  const matches = value.toString().match(/\d+/g);

  if (!matches) return 0;

  return Math.max(...matches.map(Number));
}

return items.map(entry => {

  const $json = entry.json;

  const skills = [
    ...($json.skills || []),
    ...($json.programmingLanguages || []),
    ...($json.frameworks || []),
    ...($json.databases || []),
    ...($json.cloudPlatforms || []),
    ...($json.tools || [])
  ]
  .map(s => s.toLowerCase().trim());

  const candidateExperience = Number($json.yearsExperience || 0);

  const requiredSkills =
    ($json["Required Skills"] || "")
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);

  const preferredSkills =
    ($json["Preferred Skills"] || "")
      .split(",")
      .map(s => s.trim())
      .filter(Boolean);

  const minimumExperience = extractYears($json["Minimum Experience"]);
  const minimumScore = Number($json["Minimum Score"] || 70);

  const matchedRequired = [];
  const missingRequired = [];

  requiredSkills.forEach(skill => {

    if (fuzzyMatch(skill, skills)) {
      matchedRequired.push(skill);
    } else {
      missingRequired.push(skill);
    }

  });

  const matchedPreferred = [];

  preferredSkills.forEach(skill => {

    if (fuzzyMatch(skill, skills)) {
      matchedPreferred.push(skill);
    }

  });

  // -----------------------------
  // SCORING
  // -----------------------------

  let score = 0;

  // Required Skills = 60%

  if (requiredSkills.length) {
    score +=
      (matchedRequired.length / requiredSkills.length) * 60;
  }

  // Preferred Skills = 20%

  if (preferredSkills.length) {
    score +=
      (matchedPreferred.length / preferredSkills.length) * 20;
  }

  // Experience = 20%

  if (candidateExperience >= minimumExperience) {

    score += 20;

  } else if (minimumExperience > 0) {

    score +=
      (candidateExperience / minimumExperience) * 20;

  }

  score = Math.round(score);

  // -----------------------------
  // DECISION
  // -----------------------------

  let recommendation = "";
  let status = "";

  if (score >= minimumScore) {

    recommendation = "Interview";
    status = "Shortlisted";

  } else if (score >= minimumScore * 0.7) {

    recommendation = "Manual Review";
    status = "Screening";

  } else {

    recommendation = "Reject";
    status = "Rejected";

  }

  // -----------------------------
  // REASONING
  // -----------------------------

  const reasoning =
    `Matched ${matchedRequired.length}/${requiredSkills.length} required skills, ` +
    `${matchedPreferred.length}/${preferredSkills.length} preferred skills, ` +
    `${candidateExperience} years of experience.`;

  return {

    json: {

      ...$json,

      fitScore: score,

      matchedRequiredSkills: matchedRequired,

      missingRequiredSkills: missingRequired,

      matchedPreferredSkills: matchedPreferred,

      recommendation,

      status,

      reasoning

    }

  };

});

